mapper.select:
SELECT product_num, product_name, product_price, product_img, local_gu_name, category_num
FROM product
WHERE category_num = (
SELECT category_num FROM category WHERE category_name = #{categoryName}
)order by product_num desc

SELECT p.*, c.category_name
FROM product p
JOIN category c ON p.category_num = c.category_num
WHERE p.product_name LIKE CONCAT('%', #{searchTerm}, '%')

  AND c.category_name = #{categoryName}


  AND p.local_gu_name = #{localGuName}
